 static Material Mat(string n,Color color,float smooth=.25f){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n,color=color,enableInstancing=true};m.SetFloat("_Smoothness",smooth);AssetDatabase.CreateAsset(m,F+"/Materials/"+n+".mat");return m;}
 static GameObject Box(string n,Transform parent,Vector3 pos,Vector3 scale,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 public static void Build(){if(File.Exists(Scene))throw new Exception("Refuse overwrite polish scene");foreach(var d in new[]{"Scenes","Materials","Models","Lighting","Documentation"})Directory.CreateDirectory(F+"/"+d);AssetDatabase.Refresh();EditorSceneManager.OpenScene(Old);var env=UnityEngine.Object.FindAnyObjectByType<EnvironmentPresentation>();
 // Clone every referenced material before editing; no shared source asset mutation.
 var mapping=new Dictionary<Material,Material>();foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>{if(!m)return m;if(!mapping.ContainsKey(m)){var copy=new Material(m);copy.name=m.name+" v2";AssetDatabase.CreateAsset(copy,F+"/Materials/Derivative_"+mapping.Count+".mat");mapping[m]=copy;}return mapping[m];}).ToArray();}
 var ceramic=Mat("Warm ceramic",new Color(.82f,.83f,.79f),.23f);var metal=Mat("Brushed frame",new Color(.32f,.34f,.33f),.3f);metal.SetFloat("_Metallic",.55f);var dark=Mat("Recessed seals",new Color(.08f,.1f,.105f),.2f);var accent=Mat("Safety ochre",new Color(.65f,.3f,.13f));
 foreach(var rib in UnityEngine.Object.FindObjectsByType<MeshFilter>().Where(x=>x.name=="Batched triangulated structural seams")){ // Sparse structural arcs remove dense shimmering diagonal clutter.
 var dome=UnityEngine.Object.FindObjectsByType<Transform>().First(x=>new[]{"Crew Dome","Laboratory Dome","Life Support Dome"}.Contains(x.name)&&Vector3.Distance(x.position,rib.transform.position)<.1f);var verts=new List<Vector3>();var triangles=new List<int>();Action<Vector3,Vector3> beam=(a,b)=>{Vector3 axis=(b-a).normalized,u=Vector3.Cross(axis,Vector3.up);if(u.sqrMagnitude<.01f)u=Vector3.right;u.Normalize();Vector3 v=Vector3.Cross(axis,u);int start=verts.Count;for(int e=0;e<2;e++)for(int j=0;j<4;j++)verts.Add((e==0?a:b)+(u*Mathf.Cos(j*Mathf.PI/2)+v*Mathf.Sin(j*Mathf.PI/2))*.035f);for(int j=0;j<4;j++){int k=(j+1)%4;triangles.AddRange(new[]{start+j,start+k,start+j+4,start+k,start+k+4,start+j+4});}};
 Func<float,float,Vector3> point=(a,b)=>Vector3.Scale(new Vector3(Mathf.Cos(a)*Mathf.Cos(b),Mathf.Sin(a),Mathf.Cos(a)*Mathf.Sin(b))*1.006f,dome.localScale);
 for(int longitude=0;longitude<12;longitude++)for(int k=0;k<12;k++)beam(point(k*Mathf.PI/24,longitude*Mathf.PI/6),point((k+1)*Mathf.PI/24,longitude*Mathf.PI/6));for(int ring=1;ring<5;ring++)for(int k=0;k<48;k++)beam(point(ring*Mathf.PI/12,k*Mathf.PI/24),point(ring*Mathf.PI/12,(k+1)*Mathf.PI/24));var mesh=new Mesh{name=dome.name+" sparse frame"};mesh.vertices=verts.ToArray();mesh.triangles=triangles.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,F+"/Models/"+dome.name+"_Frame.asset");rib.sharedMesh=mesh;rib.GetComponent<Renderer>().sharedMaterial=metal;dome.GetComponent<Renderer>().sharedMaterial=ceramic;}
 foreach(var door in env.closedAirlocks){if(!door)continue;for(int side=-1;side<=1;side+=2)Box("Airlock pressure frame",door,new Vector3(0,0,side*.55f),new Vector3(1.9f,1.12f,.075f),metal);Box("Door center seal",door,new Vector3(.8f,0,0),new Vector3(.3f,.92f,.025f),dark);Box("Door identification stripe",door,new Vector3(.85f,.27f,0),new Vector3(.35f,.035f,.85f),accent);}
 // Original, locally generated photovoltaic cell grid; no third-party texture download.
 var tex=new Texture2D(256,256,TextureFormat.RGB24,false);for(int y=0;y<256;y++)for(int x=0;x<256;x++){bool edge=x%32<2||y%64<2;bool bus=x%8==0;tex.SetPixel(x,y,edge?new Color(.38f,.4f,.39f):bus?new Color(.15f,.22f,.25f):new Color(.035f,.07f,.1f));}tex.Apply();File.WriteAllBytes(F+"/Materials/PhotovoltaicGrid.png",tex.EncodeToPNG());AssetDatabase.Refresh();var solar=Mat("Photovoltaic cell laminate",Color.white,.32f);solar.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(F+"/Materials/PhotovoltaicGrid.png"));foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>().Where(x=>x.name=="Photovoltaic cells"))r.sharedMaterial=solar;
 foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>().Where(x=>x.name.StartsWith("Distant rocky massif"))){t.position=new Vector3(t.position.x,-10,t.position.z);t.localScale=new Vector3(110,50+Mathf.Abs(t.position.x)%35,85);}
 env.sky=new Material(env.sky);AssetDatabase.CreateAsset(env.sky,F+"/Lighting/PolishSky.mat");RenderSettings.skybox=env.sky;for(int i=0;i<env.lighting.Length;i++){var preset=UnityEngine.Object.Instantiate(env.lighting[i]);AssetDatabase.CreateAsset(preset,F+"/Lighting/Preset_"+i+".asset");env.lighting[i]=preset;if(i==2){preset.sunEuler=new Vector3(16,-62,0);preset.sunColor=new Color(1,.78f,.57f);preset.sky=new Color(.27f,.21f,.18f);preset.horizon=new Color(.67f,.44f,.3f);preset.intensity=1.25f;preset.fogEnd=430;EditorUtility.SetDirty(preset);}}
 foreach(var volume in UnityEngine.Object.FindObjectsByType<Volume>()){if(!volume.sharedProfile)continue;var profile=UnityEngine.Object.Instantiate(volume.sharedProfile);profile.components=volume.sharedProfile.components.Select(c=>UnityEngine.Object.Instantiate(c)).ToList();AssetDatabase.CreateAsset(profile,F+"/Lighting/PolishVolume.asset");foreach(var c in profile.components)AssetDatabase.AddObjectToAsset(c,profile);volume.sharedProfile=profile;if(profile.TryGet<ColorAdjustments>(out var grade)){grade.postExposure.Override(.1f);grade.contrast.Override(6);grade.saturation.Override(-7);}}
 var registry=UnityEngine.Object.Instantiate(env.game.registry);registry.missionId="mission.red_horizon.visual_polish.v2";AssetDatabase.CreateAsset(registry,F+"/Documentation/PolishRegistry.asset");env.game.registry=registry;var polish=new GameObject("V2 presentation — source gameplay preserved").AddComponent<VisualPolishPresentation>();polish.environment=env;env.ApplyLighting(2);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(Scene);Begin("After");}
