 static void Begin(string l){EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Show();Directory.CreateDirectory(Out+"/Screenshots");SessionState.SetString("Polish.Capture",l);EditorApplication.isPlaying=true;Application.runInBackground=true;}
 static void Tick(){if(!EditorApplication.isPlaying)return;if(SessionState.GetBool("Polish.Benchmark",false)){SessionState.SetBool("Polish.Benchmark",false);new GameObject("Temporary benchmark — not saved").AddComponent<PolishBenchmark>().output=Out+"/Editor_Frame_Cadence.txt";}var pending=SessionState.GetString("Polish.Capture","");if(pending!=""){SessionState.SetString("Polish.Capture","");label=pending;shot=0;finish=false;next=EditorApplication.timeSinceStartup+3;}if(label==null||EditorApplication.timeSinceStartup<next)return;if(finish){EditorApplication.Exit(0);return;}var env=UnityEngine.Object.FindAnyObjectByType<EnvironmentPresentation>();if(!env||!env.game.initialized)return;env.game.testing=true;env.game.prototype.follow.enabled=false;cam=env.scenic;cam.enabled=true;env.ApplyLighting(2);var positions=new[]{new Vector3(20,22,-104),new Vector3(-40,2.1f,-73),new Vector3(-9,3,-102),new Vector3(55,7,-76),new Vector3(44,4,15)};var targets=new[]{new Vector3(-43,4,-43),new Vector3(-47,2,-53),new Vector3(-15,1,-93),new Vector3(35,1,-56),new Vector3(35,1,23)};var names=new[]{"HabitatOverview","AstronautThirdPerson","RoverChase","SolarFarm","ResearchZone"};if(shot%2==0){int i=shot/2;cam.transform.position=positions[i];cam.transform.LookAt(targets[i]);cam.fieldOfView=58;}else {int i=shot/2;ScreenCapture.CaptureScreenshot(Out+"/Screenshots/"+label+"_"+names[i]+"_GameView.png");var rt=new RenderTexture(1600,900,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(Out+"/Screenshots/"+label+"_"+names[i]+"_CameraOnly.png",tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}shot++;next=EditorApplication.timeSinceStartup+2;if(shot==10){finish=true;next+=2;}}
